/**
 * Generate robots.txt, sitemap.xml and llms.txt into public/.
 *
 * GENERATED by the Misaki Studio exporter — do not edit by hand. Your changes
 * are replaced on the next export. It reads src/seo/pages.json, which carries
 * what each page's author set in the editor's SEO panel.
 *
 * SITE_URL is read HERE, at build time, so one export can be published to a
 * preview host and to a real domain without being re-exported. Without it only
 * robots.txt is written: a sitemap and an llms.txt need absolute urls, and
 * llms.txt especially — it is fetched and handed to a model detached from its
 * origin, where a relative path resolves to nothing.
 */
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const publicDir = path.join(root, "public");

/** Read a key from the environment, falling back to .env. No dependency. */
const readEnv = (key) => {
  if (process.env[key]) return String(process.env[key]).trim();
  try {
    const line = fs
      .readFileSync(path.join(root, ".env"), "utf8")
      .split(/\r?\n/)
      .find((candidate) => candidate.startsWith(key + "="));
    return line ? line.slice(key.length + 1).trim() : "";
  } catch {
    return "";
  }
};

const readPages = (file) => {
  try {
    const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
    return Array.isArray(parsed?.pages) ? parsed.pages : [];
  } catch {
    // Missing or corrupt. robots.txt is still worth writing, and a build must
    // not fail over this.
    return [];
  }
};

// pages.json is written by the exporter and replaced on every export.
// pages.extra.json is OPTIONAL and hand-written: a site whose repo also holds
// pages the project knows nothing about — hand-written routes beside the
// exported ones — lists them there so they still reach the sitemap and
// llms.txt. It is never overwritten. Extras lose to exported entries on the
// same route, so moving a page into the project is what takes over.
const exported = readPages(path.join(root, "src", "seo", "pages.json"));
const extraRoutes = readPages(path.join(root, "src", "seo", "pages.extra.json"));
const pages = [
  ...exported,
  ...extraRoutes.filter(
    (extra) => !exported.some((page) => page.route === extra.route),
  ),
].sort((a, b) => a.route.localeCompare(b.route));

/**
 * When a route's page was last changed, as YYYY-MM-DD, from git.
 *
 * <lastmod> is what tells a crawler which pages are worth re-fetching; without
 * it every page looks equally stale. Derived rather than authored, because a
 * date a human maintains is a date that goes out of date and lies. Omitted
 * entirely when git cannot say — a wrong lastmod teaches a crawler to distrust
 * the file.
 */
const lastModified = (route) => {
  const candidates = [
    path.join(root, "src", "pages", route === "/" ? "index.tsx" : route + ".tsx"),
    path.join(root, "src", "pages", route === "/" ? "index.tsx" : route + "/index.tsx"),
  ];
  const file = candidates.find((candidate) => fs.existsSync(candidate));
  if (!file) return undefined;
  try {
    const out = execFileSync("git", ["log", "-1", "--format=%cI", "--", file], {
      cwd: root,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
    return out ? out.slice(0, 10) : undefined;
  } catch {
    return undefined;
  }
};

const origin = readEnv("SITE_URL").replace(/\/$/, "");
const siteName = readEnv("SITE_NAME") || "Site";
const absolute = (route) => (route === "/" ? origin + "/" : origin + route + "/");
const indexable = pages.filter((page) => page.index !== false);

fs.mkdirSync(publicDir, { recursive: true });

// Crawling is allowed everywhere on purpose. Pages marked not-indexed carry a
// noindex meta tag instead, and the two must never be combined: a Disallow stops
// the crawler FETCHING the page, so it never reads the noindex telling it to
// stay out — and an external link can then get the bare URL indexed precisely
// because the crawler was forbidden to look.
fs.writeFileSync(
  path.join(publicDir, "robots.txt"),
  [
    "# Generated at build time — do not edit by hand.",
    "",
    "User-agent: *",
    "Allow: /",
    ...(origin ? ["", "Sitemap: " + origin + "/sitemap.xml"] : []),
    "",
  ].join("\n"),
);

// A publish directory is reused across projects, so anything not rewritten this
// run is a leftover: a stale sitemap pointing at another site's domain must
// never ship inside this one.
for (const file of ["sitemap.xml", "llms.txt"]) {
  fs.rmSync(path.join(publicDir, file), { force: true });
}

if (origin) {
  const xmlEscape = (value) =>
    value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  const urls = indexable
    .map((page) => {
      // An authored priority wins. Otherwise depth is a reasonable proxy for how
      // central a page is, which is all <priority> ever claims to express.
      const priority =
        typeof page.priority === "number"
          ? Math.min(1, Math.max(0, page.priority)).toFixed(1)
          : page.route === "/"
            ? "1.0"
            : page.route.split("/").length <= 2
              ? "0.8"
              : "0.6";
      const modified = lastModified(page.route);
      return [
        "  <url>",
        "    <loc>" + xmlEscape(absolute(page.route)) + "</loc>",
        modified ? "    <lastmod>" + modified + "</lastmod>" : undefined,
        "    <priority>" + priority + "</priority>",
        "  </url>",
      ]
        .filter(Boolean)
        .join("\n");
    })
    .join("\n");
  fs.writeFileSync(
    path.join(publicDir, "sitemap.xml"),
    '<?xml version="1.0" encoding="UTF-8"?>\n' +
      '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' +
      urls +
      "\n</urlset>\n",
  );

  // The llmstxt.org convention: a plain-text map for models that fetch pages but
  // never run JavaScript.
  const oneLine = (text) => text.replace(/\s*\n+\s*/g, " ").trim();
  const titleOf = (page) =>
    page.title ||
    (page.route === "/"
      ? siteName
      : (page.route.split("/").filter(Boolean).pop() || "")
          .replace(/[-_]+/g, " ")
          .replace(/\b\w/g, (character) => character.toUpperCase()));
  // The llms text when there is one, otherwise the description — the fallback
  // runs both ways, so filling in either field alone still yields a useful file.
  const blurbOf = (page) => page.llms || page.description;
  const home = pages.find((page) => page.route === "/");
  const homeBlurb = home ? blurbOf(home) : undefined;
  fs.writeFileSync(
    path.join(publicDir, "llms.txt"),
    [
      "# " + siteName,
      // A blockquote CAN span lines, so the home page's paragraphs survive.
      ...(homeBlurb
        ? [
            "",
            homeBlurb
              .split(/\n/)
              .map((line) => ("> " + line.trim()).trimEnd())
              .join("\n"),
          ]
        : []),
      "",
      "## Pages",
      // A list ITEM cannot: a raw newline would end it and turn the rest into a
      // stray paragraph, so these are flattened.
      ...indexable.map((page) => {
        const label = "- [" + titleOf(page) + "](" + absolute(page.route) + ")";
        const blurb = blurbOf(page);
        return blurb ? label + ": " + oneLine(blurb) : label;
      }),
      "",
    ].join("\n"),
  );
}

console.log(
  "  seo-files: " +
    pages.length +
    " page(s), " +
    indexable.length +
    " indexable" +
    (origin
      ? " -> public/robots.txt, public/sitemap.xml, public/llms.txt"
      : " -> public/robots.txt (no SITE_URL: sitemap and llms.txt need absolute urls, skipped)"),
);
